{%- if product -%}
{%- assign info_id = 'model-info-inline-' | append: product.id -%}

<div id="{{ info_id }}" class="model-info-inline" aria-live="polite"></div>

<style>
  #{{ info_id }}{ margin:8px 0 12px; font-size:13px; line-height:1.35; color:#111; }
  #{{ info_id }} .mi{ display:inline; }
  #{{ info_id }} .sep{ margin:0 .4em; opacity:.6; }
  #{{ info_id }} .label{ font-weight:600; margin-right:.5em; }
</style>

<script>
(function(){
  var inlineBoxId = {{ info_id | json }};
  var currentHTML = '';

  function cm2in(cm){ return cm * 0.3937008; }
  function ftIn(cm){
    var totalIn = cm2in(cm);
    var ft = Math.floor(totalIn/12);
    var inch = Math.round(totalIn%12);
    return ft + "'" + inch + "″";
  }
  function numFromCm(txt){
    var m = (txt || '').match(/(\d+(?:\.\d+)?)\s*cm/);
    return m ? parseFloat(m[1]) : null;
  }

  function buildOneLiner(alt){
    var parts = (alt || '').split('|').map(function(s){ return s.trim(); });
    if(parts.length < 3) return '';

    var size = parts[0]
      .replace(/Model wears\s*/i,'')
      .replace(/Model draagt maat\s*/i,'')
      .replace(/Model trägt Größe\s*/i,'')
      .trim();

    var hCm = numFromCm(parts[1]);
    var wCm = numFromCm(parts[2]);

    var bits = [];

    // Size
    if(size) bits.push('<span class="mi">'+ size +'</span>');

    // Height
    if(hCm){
      // toggle "H" label by uncommenting next line:
      // bits.push('<span class="mi">H '+ hCm + ' cm (' + ftIn(hCm) + ')</span>');
      bits.push('<span class="mi">'+ hCm + ' cm (' + ftIn(hCm) + ')</span>');
    }

    // Waist
    if(wCm){
      var wIn = Math.round(cm2in(wCm));
      // toggle "W" label by uncommenting next line:
      // bits.push('<span class="mi">W '+ wCm + ' cm ('+ wIn +'″)</span>');
      bits.push('<span class="mi">'+ wCm + ' cm ('+ wIn +'″)</span>');
    }

    return '<span class="label">Model:</span>' + bits.join('<span class="sep">·</span>');
  }

  function setInline(html){
    var box = document.getElementById(inlineBoxId);
    if(!box) return;
    if(html !== currentHTML){
      box.innerHTML = html;
      currentHTML = html;
    }
  }

  function getActiveGalleryImg(){
    return document.querySelector('.product-gallery__media.is-selected img') ||
           document.querySelector('.product-gallery__media.is-selected picture img') ||
           document.querySelector('.product__media-item.is-active img') ||
           document.querySelector('.product__media-item.is-active picture img') ||
           document.querySelector('.product__media img');
  }

  function update(){
    var img = getActiveGalleryImg();
    setInline(img && img.alt ? buildOneLiner(img.alt) : '');
  }

  function watch(){
    var gal = document.querySelector('.product-gallery, .product__media-list, .product__media');
    if(gal){
      new MutationObserver(update).observe(gal, { attributes:true, subtree:true, childList:true, attributeFilter:['class','aria-hidden'] });
    }
    update();
  }

  ['shopify:section:load','variant:change'].forEach(function(ev){
    document.addEventListener(ev, function(){ setTimeout(watch,50); });
  });
  document.addEventListener('change', function(e){
    if(e.target && e.target.matches('[name="id"]')) setTimeout(watch,50);
  });

  watch();
})();
</script>
{%- endif -%}

{%- comment -%}
CURVJEANS — Centered Social Proof (3 avatars, localized)
• Spacing after number, larger bottom margin
• EN/NL/DE copy (short & natural)
• Clickable → smooth-scroll to Loox reviews
{%- endcomment -%}

<a class="cj-inline-proof" href="#pdp-reviews" aria-label="Read reviews">
  <span class="cj-inline-proof__images" aria-hidden="true">
    <img loading="lazy"
         src="https://cdn.shopify.com/s/files/1/0864/5165/0895/files/488167940_645529638333261_8577394906245230255_n_1.jpg?v=1745295938"
         alt=""
         class="cj-inline-proof__profile">
    <img loading="lazy"
         src="https://cdn.shopify.com/s/files/1/0864/5165/0895/files/482449966_1709516659776039_2956674113585282466_n_1.jpg?v=1745295938"
         alt=""
         class="cj-inline-proof__profile">
    <img loading="lazy"
         src="https://cdn.shopify.com/s/files/1/0864/5165/0895/files/474474013_633097669170307_5994573843549457098_n_1.jpg?v=1745295937"
         alt=""
         class="cj-inline-proof__profile">
  </span>
  <span class="cj-inline-proof__text" id="cj-fit-text">
    <strong>10,000+</strong> are obsessed
    <img loading="lazy"
         src="https://cdn.shopify.com/s/files/1/0864/5165/0895/files/verified.webp?v=1726649878"
         alt=""
         class="cj-inline-proof__verified">
  </span>
</a>

<style>
.cj-inline-proof{
  display:flex; justify-content:left; align-items:le; flex-wrap:wrap;
  gap:10px;
  width:100%;
  margin:24px 0 16px;               /* bottom margin increased to 16px */
  text-decoration:none;
  -webkit-tap-highlight-color: transparent;
}
.cj-inline-proof:active{ opacity:.92; }

.cj-inline-proof__images{ display:flex; position:relative; }
.cj-inline-proof__profile{
  width:28px; height:28px;
  border-radius:50%;
  border:2px solid #fff;
  margin-right:-8px;
  box-shadow:0 0 4px rgba(0,0,0,.08);
}
.cj-inline-proof__profile:last-child{ margin-right:0; }

.cj-inline-proof__text{
  font-size:14px; line-height:1.35; color:#222; font-weight:500;
  display:flex; align-items:center; text-align:center;
}
.cj-inline-proof__text strong{
  font-weight:700;
  margin-right:4px;                 /* adds a nice gap after “10,000+” */
}

.cj-inline-proof__verified{
  width:15px; height:15px; margin-left:6px; display:inline-block; vertical-align:middle;
}

@media (max-width:360px){
  .cj-inline-proof__text{ font-size:13.2px; }
  .cj-inline-proof__profile{ width:26px; height:26px; margin-right:-7px; }
}
</style>

<script>
(function(){
  /* i18n */
  var fit = document.getElementById('cj-fit-text');
  if (fit){
    var p = location.pathname || '';
    if (p.startsWith('/nl')){
      fit.innerHTML =
        '<strong>10.000+</strong> girls zijn obsessed' +
        '<img loading="lazy" src="https://cdn.shopify.com/s/files/1/0864/5165/0895/files/verified.webp?v=1726649878" alt="" class="cj-inline-proof__verified">';
    } else if (p.startsWith('/de')){
      fit.innerHTML =
        '<strong>10.000+</strong>Girls sind besessen
        '<img loading="lazy" src="https://cdn.shopify.com/s/files/1/0864/5165/0895/files/verified.webp?v=1726649878" alt="" class="cj-inline-proof__verified">';
    }
  }

  /* Smooth scroll to reviews (common Loox selectors) */
  var targets = ['#pdp-reviews', '#looxReviews', '#loox-reviews', '#looxReviewsWidget', '.loox-widget'];
  function findReviews(){
    for (var i=0;i<targets.length;i++){ var el = document.querySelector(targets[i]); if(el) return el; }
    return null;
  }
  function stickyOffset(){
    var h=0;
    var header = document.querySelector('.shopify-section-header-sticky, .header, .site-header, header');
    var ann    = document.querySelector('.announcement-bar, .shopify-section-announcement-bar');
    if (ann)    h += ann.offsetHeight||0;
    if (header) h += header.offsetHeight||0;
    return Math.max(h,56);
  }
  document.addEventListener('click', function(e){
    var link = e.target.closest('.cj-inline-proof');
    if(!link) return;
    var dest = findReviews();
    if(dest){
      e.preventDefault();
      var top = dest.getBoundingClientRect().top + window.pageYOffset - stickyOffset();
      window.scrollTo({ top: top, behavior: 'smooth' });
    }
  }, {passive:false});
})();
</script>
